{
  "status": "SUPPORTED",
  "task_summary": "Find compatible parts and tools, fasten them at the target, and return the tool to the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "the marked workbench location",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["workbench surface", "assembly point"],
        "required_properties": ["stable", "accessible"]
      },
      {
        "id": "component_part",
        "entity_kind": "OBJECT",
        "function": "a physical part to be attached",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["part", "module", "piece"],
        "required_properties": ["compatible with target", "movable"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "an implement for joining parts",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "tool"],
        "required_properties": ["capable of fastening", "manipulatable"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "the wooden table surface",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["flat surface", "stable"]
      },
      {
        "id": "storage_unit",
        "entity_kind": "FIXED_TARGET",
        "function": "cabinet or drawers containing items",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "drawer", "cupboard"],
        "required_properties": ["enclosed", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "component_part fits fastening_target",
        "participant_roles": ["component_part", "fastening_target"]
      ,
      "required": true
      },
      {
        "id": "relation_2",
        "relation": "fastening_tool rests on workbench",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "search_for_items",
        "participant_roles": ["storage_unit", "component_part", "fastening_tool"],
        "operation_count": 2
      },
      {
        "id": "operation_2",
        "operation": "perform_fastening",
        "participant_roles": ["fastening_tool", "component_part", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "operation_3",
        "operation": "place_tool",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "black_tray_on_table",
          "visual_description": "Black rectangular tray sitting on the wooden workbench surface"
        }
      ],
      "component_part": [
        {
          "label": "yellow_object",
          "visual_description": "Yellow rectangular object resting on the black tray"
        }
      ],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden table with drawers and a cabinet nearby"
        }
      ],
      "storage_unit": [
        {
          "label": "blue_cabinet",
          "visual_description": "Tall blue cabinet standing next to the workbench"
        },
        {
          "label": "blue_drawers",
          "visual_description": "Two blue drawers underneath the workbench"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "region_1",
        "label": "blue_cabinet_interior",
        "visual_description": "Closed blue cabinet door",
        "reason": "Enclosed structure potentially containing tools or parts"
      },
      {
        "id": "region_2",
        "label": "blue_drawer_interiors",
        "visual_description": "Closed blue drawers under the table",
        "reason": "Enclosed storage spaces potentially containing tools or parts"
      }
    ],
    "inspection_order": [
      "region_1",
      "region_2",
      "black_tray_on_table"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
